css:
/* Canopy: pebble-soft shapes, a leaf-shaped user bubble, dappled light behind the chat. */
[data-slot="composer-host"] { border-radius: 22px !important; }
[data-user-message-bubble] { border-radius: 20px 20px 6px 20px !important; }
.chat-markdown-codeblock { border-radius: 14px !important; }
[data-thread-item] { border-radius: 14px !important; }
[data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="dialog-popup"], [data-thread-details-card] { border-radius: 18px !important; }

/* Morning: warm sun patches falling through leaves. */
:root:not(.dark) [data-workspace-area="conversation"] {
  background-image:
    radial-gradient(ellipse 520px 360px at 10% 6%, rgba(255, 220, 120, 0.55), transparent 70%),
    radial-gradient(ellipse 420px 300px at 92% 28%, rgba(255, 228, 140, 0.45), transparent 70%),
    radial-gradient(ellipse 620px 380px at 72% 96%, rgba(150, 195, 110, 0.32), transparent 70%),
    radial-gradient(ellipse 360px 260px at 4% 62%, rgba(255, 226, 140, 0.40), transparent 70%) !important;
}

/* Night: fireflies in the side margins (clear of the text column) and a little moonlight from the top. */
.dark [data-workspace-area="conversation"] {
  background-image:
    radial-gradient(circle at 5% 18%, rgba(250, 225, 120, 0.95) 0 2px, rgba(245, 215, 110, 0.22) 4px, rgba(245, 215, 110, 0.06) 10px, transparent 18px),
    radial-gradient(circle at 8% 41%, rgba(250, 225, 120, 0.80) 0 1.5px, rgba(245, 215, 110, 0.18) 4px, rgba(245, 215, 110, 0.05) 9px, transparent 16px),
    radial-gradient(circle at 7% 66%, rgba(250, 225, 120, 0.90) 0 2px, rgba(245, 215, 110, 0.20) 4px, rgba(245, 215, 110, 0.06) 10px, transparent 18px),
    radial-gradient(circle at 3% 90%, rgba(250, 225, 120, 0.70) 0 1.5px, rgba(245, 215, 110, 0.16) 4px, rgba(245, 215, 110, 0.05) 9px, transparent 15px),
    radial-gradient(circle at 92% 9%, rgba(250, 225, 120, 0.85) 0 1.5px, rgba(245, 215, 110, 0.18) 4px, rgba(245, 215, 110, 0.05) 9px, transparent 16px),
    radial-gradient(circle at 88% 34%, rgba(250, 225, 120, 0.95) 0 2px, rgba(245, 215, 110, 0.22) 4px, rgba(245, 215, 110, 0.06) 10px, transparent 18px),
    radial-gradient(circle at 96% 58%, rgba(250, 225, 120, 0.75) 0 1.5px, rgba(245, 215, 110, 0.16) 4px, rgba(245, 215, 110, 0.05) 9px, transparent 15px),
    radial-gradient(circle at 86% 82%, rgba(250, 225, 120, 0.90) 0 2px, rgba(245, 215, 110, 0.20) 4px, rgba(245, 215, 110, 0.06) 10px, transparent 18px),
    radial-gradient(ellipse 900px 380px at 50% -10%, rgba(198, 241, 157, 0.07), transparent 70%) !important;
}

/* Links and "Working" in stream blue, apart from the green "Done". */
:root:not(.dark) { --info: #235b80 !important; --info-foreground: #235b80 !important; }
.dark { --info: #8ec9e8 !important; --info-foreground: #8ec9e8 !important; }
:root:not(.dark) ::selection { background: #d3e3c2; color: #1d2b16; }
.dark ::selection { background: #3a5a2c; color: #f2f8ec; }
